import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the immutable v1 corpus generated by `color_matching` at a82aec5.
final class WeightedSquaredErrorParityCorpusTests: XCTestCase {
    private let expectedAlgorithmVersion = 1
    private let scoreAccuracy = 1e-12

    func testWeightedSquaredErrorMatchesCommittedParityCorpus() throws {
        let corpus = try loadCorpus()
        XCTAssertEqual(corpus.algorithmVersion, expectedAlgorithmVersion)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")

        for scenario in corpus.scenarios {
            try assertScorerParity(for: scenario)
            try assertSelectionParity(for: scenario)
        }
    }

    private func assertScorerParity(for scenario: Scenario) throws {
        let scorer = WeightedSquaredErrorScorer()
        let target = TargetResponseVector(channels(from: scenario.target.channels))
        let weights = makeWeights(scenario.weights)

        for expected in scenario.expected.scores {
            let candidate = try XCTUnwrap(
                scenario.palette.first(where: { $0.index == expected.index }),
                "Missing candidate \(expected.index) in \(scenario.id)"
            )
            let result = scorer.score(candidate: makeColor(candidate), target: target, weights: weights)

            switch (expected.score, result) {
            case (.excluded, .excluded):
                break
            case (.value(let expectedScore), .score(let actualScore)):
                XCTAssertEqual(actualScore, expectedScore, accuracy: scoreAccuracy, scenario.id)
            default:
                XCTFail("Unexpected score for candidate \(candidate.index) in \(scenario.id): \(result)")
            }
        }
    }

    private func assertSelectionParity(for scenario: Scenario) throws {
        let activeConditions = scenario.weights.compactMap { key, weight in
            LightingCondition(rawValue: key).map { ($0, weight) }
        }.filter { $0.1 > 0 }

        // A target missing an active channel is represented directly in the scorer
        // assertion above. CompositionSolver correctly rejects absent source grids,
        // so only replay selector scenarios with a complete target vector here.
        guard activeConditions.allSatisfy({ scenario.target.channels[$0.0.rawValue] != nil }) else {
            XCTAssertNil(scenario.expected.selectedIndex, scenario.id)
            XCTAssertNil(scenario.expected.error, scenario.id)
            return
        }

        let grids = Dictionary(uniqueKeysWithValues: activeConditions.map { condition, _ in
            (condition, BrightnessGrid(width: 1, height: 1, values: [scenario.target.channels[condition.rawValue]!]))
        })
        let result = try CompositionSolver().solve(
            palette: scenario.palette.map(makeColor),
            sourceGrids: grids,
            weights: makeWeights(scenario.weights)
        )

        XCTAssertEqual(result.colorIndex(x: 0, y: 0), scenario.expected.selectedIndex, scenario.id)
        if let expectedError = scenario.expected.error {
            XCTAssertEqual(result.error(x: 0, y: 0), expectedError, accuracy: scoreAccuracy, scenario.id)
        } else {
            XCTAssertTrue(result.error(x: 0, y: 0).isInfinite, scenario.id)
        }

        if scenario.expected.tieBroke == true {
            XCTAssertEqual(scenario.expected.selectedIndex, scenario.expected.tiedIndices.min(), scenario.id)
        }
    }

    private func loadCorpus() throws -> Corpus {
        let testDirectory = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        let fixture = testDirectory.appendingPathComponent("Fixtures/weighted-squared-error-v1.json")
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(Corpus.self, from: Data(contentsOf: fixture))
    }

    private func makeColor(_ vector: Vector) -> PaletteColor {
        PaletteColor(
            id: vector.index!,
            hex: vector.hexColor,
            rgb: RGBColor(hex: vector.hexColor)!,
            responses: channels(from: vector.channels).mapValues(IlluminationResponse.init(brightness:))
        )
    }

    private func channels(from values: [String: Double]) -> [LightingCondition: Double] {
        Dictionary(uniqueKeysWithValues: values.compactMap { key, value in
            LightingCondition(rawValue: key).map { ($0, value) }
        })
    }

    private func makeWeights(_ values: [String: Double]) -> ChannelWeights {
        ChannelWeights(
            white: values["white", default: 0],
            red: values["red", default: 0],
            green: values["green", default: 0],
            blue: values["blue", default: 0],
            lps: values["lps", default: 0]
        )
    }
}

private struct Corpus: Decodable {
    let algorithmVersion: Int
    let missingPolicy: String
    let scenarios: [Scenario]
    let scorer: String
    let selection: String
}

private struct Scenario: Decodable {
    let expected: Expected
    let id: String
    let palette: [Vector]
    let target: Vector
    let weights: [String: Double]
}

private struct Vector: Decodable {
    let channels: [String: Double]
    let hexColor: String
    let index: Int?
}

private struct Expected: Decodable {
    let error: Double?
    let scores: [ExpectedScore]
    let selectedIndex: Int?
    let tieBroke: Bool?
    let tiedIndices: [Int]
}

private struct ExpectedScore: Decodable {
    let index: Int
    let score: CorpusScore
}

private enum CorpusScore: Decodable {
    case excluded
    case value(Double)

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .value(value)
        } else if try container.decode(String.self) == "excluded" {
            self = .excluded
        } else {
            throw DecodingError.dataCorruptedError(in: container, debugDescription: "Unknown corpus score")
        }
    }
}
